<template>
  <div class="shared-view-embed">
    <div
      class="shared-view-frame"
      :class="{ 'touch-demo-gated': touchDemoEnabled, 'touch-demo-active': touchDemoActive }"
      ref="frame"
    >
      <iframe
        ref="viewIframe"
        :src="viewUrl"
        :title="`Saved ${viewLabel} preview`"
        loading="lazy"
        :tabindex="touchDemoEnabled && !touchDemoActive ? -1 : 0"
      ></iframe>
      <DemoInteractionGate
        v-if="touchDemoEnabled"
        :active="touchDemoActive"
        label="Explore this View"
        :open-href="openUrl"
        @activate="activateTouchDemo"
        @deactivate="deactivateTouchDemo"
      />
    </div>
    <FrameOpenLink class="shared-view-open-link" :href="openUrl">
      <template #label>
        Sample <AiViewTerm />
      </template>
      <template #action>Open it fullscreen</template>
    </FrameOpenLink>
  </div>
</template>

<script>
import AiViewTerm from '../ui/AiViewTerm.vue';
import DemoInteractionGate from '../ui/DemoInteractionGate.vue';
import FrameOpenLink from './FrameOpenLink.vue';

export default {
  name: 'EmbeddedSharedView',
  components: { AiViewTerm, DemoInteractionGate, FrameOpenLink },
  props: {
    shareId: {
      type: String,
      required: true,
    },
    viewLabel: {
      type: String,
      default: 'View',
    },
  },
  data() {
    return {
      touchDemoEnabled: false,
      touchDemoActive: false,
    };
  },
  computed: {
    viewUrl() {
      const origin = typeof window !== 'undefined' ? window.location.origin : '';
      return `${origin}${window.location.pathname}#/view/${this.shareId}?embedded=1&preview=1`;
    },
    openUrl() {
      const origin = typeof window !== 'undefined' ? window.location.origin : '';
      return `${origin}${window.location.pathname}#/view/${this.shareId}`;
    },
  },
  mounted() {
    this._onResize = () => this.scaleFrame();
    window.addEventListener('resize', this._onResize);
    this.setupTouchDemo();
    this.$nextTick(() => this.scaleFrame());
  },
  unmounted() {
    if (this._onResize) window.removeEventListener('resize', this._onResize);
    if (this._touchDemoMedia && this._onTouchDemoMedia) {
      this._touchDemoMedia.removeEventListener?.('change', this._onTouchDemoMedia);
      this._touchDemoMedia.removeListener?.(this._onTouchDemoMedia);
    }
  },
  methods: {
    setupTouchDemo() {
      this._touchDemoMedia = window.matchMedia(
        '(max-width: 700px), (max-width: 1100px) and (hover: none) and (pointer: coarse)',
      );
      this._onTouchDemoMedia = (event) => {
        this.touchDemoEnabled = event.matches;
        if (!event.matches) this.touchDemoActive = false;
      };
      this._onTouchDemoMedia(this._touchDemoMedia);
      this._touchDemoMedia.addEventListener?.('change', this._onTouchDemoMedia);
      this._touchDemoMedia.addListener?.(this._onTouchDemoMedia);
    },
    activateTouchDemo() {
      this.touchDemoActive = true;
      this.$nextTick(() => this.$refs.viewIframe?.focus({ preventScroll: true }));
    },
    deactivateTouchDemo() {
      this.touchDemoActive = false;
    },
    scaleFrame() {
      const frame = this.$refs.frame;
      const iframe = this.$refs.viewIframe;
      if (!frame || !iframe) return;
      // The View page lays out at this width; the design width sits just
      // outside the content column so the preview shows the page nearly
      // edge to edge instead of shrinking a wide desktop layout.
      const DESIGN_W = 640;
      const DESIGN_H = 650;
      const cw = frame.clientWidth;
      if (cw >= 460) {
        const scale = cw / DESIGN_W;
        iframe.style.width = `${DESIGN_W}px`;
        iframe.style.height = `${DESIGN_H}px`;
        iframe.style.transform = `scale(${scale})`;
        frame.style.height = `${Math.round(DESIGN_H * scale)}px`;
      } else {
        iframe.style.width = '100%';
        iframe.style.height = '';
        iframe.style.transform = 'none';
        frame.style.height = '';
      }
    },
  },
};
</script>

