  --frame-open-line: var(--story-line, rgba(0, 0, 0, 0.14));
  --frame-open-muted: var(--story-muted, #777777);
  --frame-open-ink: var(--story-ink, #343434);
  --frame-open-hover: rgba(0, 0, 0, 0.055);
  --frame-open-press: rgba(0, 0, 0, 0.09);
  margin: 1.3rem 0 0;
  border: 1px solid var(--story-line, rgba(0, 0, 0, 0.14));
  border-radius: 12px;
  overflow: hidden;
  background: var(--story-wash, rgba(0, 0, 0, 0.028));
}

.shared-view-frame {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.shared-view-frame iframe {
  display: block;
  width: 100%;
  height: 620px;
  border: 0;
  transform-origin: top left;
}

:global(body.dark-mode .shared-view-embed) {
  --frame-open-hover: rgba(255, 255, 255, 0.055);
  --frame-open-press: rgba(255, 255, 255, 0.09);
}

@media (max-width: 700px) {
  .shared-view-open-link { display: none; }
  .shared-view-frame.touch-demo-gated iframe { pointer-events: none; }
  .shared-view-frame.touch-demo-active iframe { pointer-events: auto; }
  .shared-view-frame iframe {
    height: 460px;
  }
}

@media (max-width: 1100px) and (hover: none) and (pointer: coarse) {
  .shared-view-open-link { display: none; }
  .shared-view-frame.touch-demo-gated iframe { pointer-events: none; }
  .shared-view-frame.touch-demo-active iframe { pointer-events: auto; }
}
</style>
